#include <stdio.h>
#include <string.h>
#include <ctype.h>

void oNormalizador(void) {
    char palavra[50] = "";
    char nome[120] = "";
    while (scanf("%49s", palavra) == 1) {
        palavra[0] = toupper(palavra[0]);
        if (nome[0] == '\0') {
            snprintf(nome, sizeof nome, "%s", palavra);
        } else {
            snprintf(nome + strlen(nome), sizeof nome - strlen(nome), " %s", palavra);
        }
    }
    printf("%s\n", nome);
}
